void Studio::runEditorTimingTransportTick(){
    auto put=[&](const char* name,bool value){transportResults.getDynamicObject()->setProperty(name,value);};
    if(transportTicks==5400){perform(stop);project=emptyProject();selectedTrack=7;currentFile={};project.patterns[0].length=16;lane()={{1.5,.25,60,.8f},{3,.5,64,.7f}};Pattern target;target.name="Part 2";target.lanes.resize(project.tracks.size());project.patterns.push_back(target);project.clips={{7,0,13,16},{7,1,48,8}};undoStack.clear();redoStack.clear();publish();showPane(pianoPane);perform(play);engine->seekRequested.store(12);setPatternSteps();auto* dialog=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent());put("nativeTimingLengthDialog",dialog!=nullptr);if(dialog){dialog->getTextEditor("value")->setText("32");dialog->exitModalState(1);}}
    if(transportTicks==5410){put("nativeTimingLengthReset",project.patterns[0].length==8&&engine->position.load()<1&&pianoStart==0&&pianoNoteCursor==0);perform(stop);keyPressed(KeyPress('A',ModifierKeys::ctrlModifier,'a'));keyPressed(KeyPress('C',ModifierKeys::ctrlModifier,'c'));perform(patternSelect,1);pianoNoteCursor=6.75;keyPressed(KeyPress('V',ModifierKeys::ctrlModifier,'v'));put("nativeTimingPaste",lane()==project.patterns[0].lanes[7]);perform(undoAction);put("nativeTimingPasteUndo",lane().empty());perform(redoAction);put("nativeTimingPasteRedo",lane()==project.patterns[0].lanes[7]);engine->position.store(6);perform(play);perform(patternSelect,0);}
    if(transportTicks==5420){put("nativeTimingPatternReset",engine->position.load()<1);perform(stop);project.songMode=true;publish();engine->seekRequested.store(15.25);perform(play);}
    if(transportTicks==5430){double beat=engine->position.load();auto heads=patternPlaybackPositions(project,7,beat);put("nativeTimingSongPhase",heads.size()==1&&std::abs(heads[0]-(beat-13))<.000001);perform(patternSelect,1);}
    if(transportTicks==5440){put("nativeTimingInactivePattern",engine->position.load()>15&&patternPlaybackPositions(project,7,engine->position.load()).empty());perform(stop);showPane(pianoPane);Image image(Image::RGB,getWidth(),getHeight(),true);Graphics g(image);paint(g);lastEditorPointer=pianoRect.getCentre();lastEditorModifiers={};perform(toolSelect,3);put("nativeTimingSelectCursor",getMouseCursor()==editorToolCursor(3));perform(toolSelect,0);put("nativeTimingDrawCursor",getMouseCursor()==editorToolCursor(0));}
    if(transportTicks==5450){engine->observedPeak.store(0);transportFrames=engine->processedFrames.load();}
    if(transportTicks==5460)put("nativeTimingStopped",!engine->playing.load()&&engine->observedPeak.load()==0&&engine->processedFrames.load()>transportFrames);
}
